<?php
namespace Azuriom\Plugin\GamingHubCore\Readers;
use Azuriom\Plugin\GamingHubCore\Contracts\CapabilityReader; use Azuriom\Plugin\GamingHubCore\Contracts\ProviderInstances; use Azuriom\Plugin\GamingHubCore\Data\ProviderInstanceData; use Azuriom\Plugin\GamingHubCore\Data\ServerStatusData; use Azuriom\Plugin\GamingHubCore\Data\SharedDataResult; use Azuriom\Plugin\GamingHubCore\Models\Server; use Carbon\CarbonImmutable;
final class ManualServerStatusReader implements CapabilityReader { public function __construct(private ProviderInstances $providers){} public function cacheTtl():int{return 0;} public function read(Server $server,ProviderInstanceData $provider):SharedDataResult{$c=$this->providers->validatedConfiguration((int)$server->getKey(),$provider->id);$dto=new ServerStatusData(state:is_string($c['status']??null)?$c['status']:'unknown',displayMessage:is_string($c['display_message']??null)&&trim($c['display_message'])!==''?trim($c['display_message']):null,observedAt:CarbonImmutable::now());return new SharedDataResult('server-status',(int)$server->getKey(),'available',$dto->toArray(),$dto->observedAt,null,$provider->providerType,$provider->id,sourceLabel:'Manual');} }
